const events = $input.first().json.events.filter(e => e.start?.dateTime && e.end?.dateTime);

const checkIfAvailable = (slotStart) => {
  const slotEnd = new Date(slotStart.getTime() + 60 * 60 * 1000);
  return !events.some(event => {
    const eventStart = new Date(event.start.dateTime);
    const eventEnd = new Date(event.end.dateTime);
    return slotStart < eventEnd && slotEnd > eventStart;
  });
};

const webhookInput = $('Edit Fields').first().json;
const after = new Date(webhookInput.start);
const before = new Date(webhookInput.end);
let slots = [];
let current = new Date(after);

while (current < before) {
  if (checkIfAvailable(current)) {
    const spoken = current.toLocaleString('en-US', {
      weekday: 'long',
      hour: 'numeric',
      minute: '2-digit',
      hour12: true,
      timeZone: 'America/New_York'
    });
    const iso = current.toISOString();
    slots.push({ id: iso, spoken });
  }
  current = new Date(current.getTime() + 60 * 60 * 1000);
}

// Build natural spoken summary
let spokenSummary = "It looks like we're fully booked.";
if (slots.length > 0) {
  const readable = slots.map(s => s.spoken);
  if (readable.length === 1) spokenSummary = `We have ${readable[0]} available.`;
  else spokenSummary = `We have ${readable.slice(0, -1).join(', ')} and ${readable[readable.length - 1]} — what works better for you?`;
}

return {
  results: [
    {
      toolCallId: $('VAPI Webhook Tool - GET Availability').first().json.body.message.toolCalls[0].id,
      result: {
        slots: JSON.stringify(slots),
        spokenSummary
      }
    }
  ]
};

